public enum ControlAvailability: Codable, Sendable, Equatable {
  case available(ControlAvailabilityAvailable)
  case blocked(ControlAvailabilityBlocked)

  private enum Tag: String, CodingKey { case state }

  public init(from decoder: any Decoder) throws {
    let c = try decoder.container(keyedBy: Tag.self)
    switch try c.decode(String.self, forKey: .state) {
    case "available": self = .available(try ControlAvailabilityAvailable(from: decoder))
    case "blocked": self = .blocked(try ControlAvailabilityBlocked(from: decoder))
    default: throw DecodingError.dataCorruptedError(forKey: .state, in: c, debugDescription: "unknown ControlAvailability")
    }
  }

  public func encode(to encoder: any Encoder) throws {
    switch self {
    case .available(let value): try value.encode(to: encoder)
    case .blocked(let value): try value.encode(to: encoder)
    }
  }
}

