  enum CodingKeys: String, CodingKey {
    case jobId
    case reportId
    case installation
    case items
    case measurements
    case parts
    case refrigerant
    case workText
    case nextAction
    case attachmentIds
  }

  public init(from decoder: any Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    jobId = try c.decode(String.self, forKey: .jobId)
    reportId = try c.decodeIfPresent(String.self, forKey: .reportId)
    installation = try c.decodeIfPresent(InstallationCheck.self, forKey: .installation)
    items = try c.decode([InspectionItemInput].self, forKey: .items)
    measurements = try c.decode([InspectionMeasurementInput].self, forKey: .measurements)
    parts = try c.decode([Part].self, forKey: .parts)
    refrigerant = try c.decode([RefrigerantRecord].self, forKey: .refrigerant)
    workText = try c.decode(String.self, forKey: .workText)
    nextAction = try c.decode(NextAction?.self, forKey: .nextAction)
    attachmentIds = try c.decode([String].self, forKey: .attachmentIds)
  }

  public func encode(to encoder: any Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(jobId, forKey: .jobId)
    try c.encodeIfPresent(reportId, forKey: .reportId)
    try c.encodeIfPresent(installation, forKey: .installation)
    try c.encode(items, forKey: .items)
    try c.encode(measurements, forKey: .measurements)
    try c.encode(parts, forKey: .parts)
    try c.encode(refrigerant, forKey: .refrigerant)
    try c.encode(workText, forKey: .workText)
    try c.encode(nextAction, forKey: .nextAction)
    try c.encode(attachmentIds, forKey: .attachmentIds)
  }
}
